import{_ as t,o as a,c as o,ah as r}from"./chunks/framework.Bja9t6Wf.js";const m=JSON.parse('{"title":"PRESS KIT: THE HORTEN MYSTERY","description":"","frontmatter":{},"headers":[],"relativePath":"en/pressemappe.md","filePath":"en/pressemappe.md"}'),i={name:"en/pressemappe.md"};function s(n,e,l,h,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="press-kit-the-horten-mystery" tabindex="-1">PRESS KIT: THE HORTEN MYSTERY <a class="header-anchor" href="#press-kit-the-horten-mystery" aria-label="Permalink to &quot;PRESS KIT: THE HORTEN MYSTERY&quot;">​</a></h1><p><strong>An Investigative Mockumentary Experiment by Volti Sodala &amp; Gemini CLI.</strong></p><hr><h2 id="⚡-project-overview" tabindex="-1">⚡ Project Overview <a class="header-anchor" href="#⚡-project-overview" aria-label="Permalink to &quot;⚡ Project Overview&quot;">​</a></h2><p>&quot;The Horten Mystery&quot; is a hybrid platform combining investigative research with political satire. We reconstruct the &quot;system of discrete influence&quot; – from Nazi-looted capital in the 1930s to the billion-dollar collapse of René Benko in 2023.</p><h3 id="core-theses" tabindex="-1">Core Theses: <a class="header-anchor" href="#core-theses" aria-label="Permalink to &quot;Core Theses:&quot;">​</a></h3><ol><li><strong>Pointillism of Money:</strong> Power today is exercised not through one large scandal, but through thousands of small &quot;dots&quot; (donation splitting, patronage, real estate valuations).</li><li><strong>Continuity of Power:</strong> The legacy of &quot;Aryanization&quot; (Alsberg Case) forms the unaddressed foundation of modern assets.</li><li><strong>The Aesthetic of Silence:</strong> How bureaucracy and justice are used to &quot;shut down&quot; unpleasant truths.</li></ol><hr><h2 id="🎭-fictional-cast" tabindex="-1">🎭 Fictional Cast <a class="header-anchor" href="#🎭-fictional-cast" aria-label="Permalink to &quot;🎭 Fictional Cast&quot;">​</a></h2><p>We stage the story with the voices and characters of:</p><ul><li><strong>Birgit Minichmayr</strong> as Heidi Horten.</li><li><strong>August Diehl</strong> as Helmut Horten.</li><li><strong>Udo Samel</strong> as August Wöginger.</li><li><strong>Oliver Masucci</strong> as Chronicler / Christian Pilnacek.</li></ul><hr><h2 id="🎮-interactive-media-tools" tabindex="-1">🎮 Interactive Media Tools <a class="header-anchor" href="#🎮-interactive-media-tools" aria-label="Permalink to &quot;🎮 Interactive Media Tools&quot;">​</a></h2><ul><li><strong><a href="/en/budget-spiel.html">Budget Rescue Simulator</a>:</strong> A playful analysis of the 4.7% deficit.</li><li><strong><a href="/en/mitmachen.html">Whistleblower Tip-Line</a>:</strong> An anonymous interface for reader tips.</li><li><strong><a href="/en/hoerbuch/audio-showcase.html">Audio Showcase</a>:</strong> AI-reconstructed character studies.</li></ul><hr><h2 id="📂-resources-for-journalists" tabindex="-1">📂 Resources for Journalists <a class="header-anchor" href="#📂-resources-for-journalists" aria-label="Permalink to &quot;📂 Resources for Journalists&quot;">​</a></h2><ul><li><strong>Website:</strong> <a href="https://dokfilm.pages.dev" target="_blank" rel="noreferrer">https://dokfilm.pages.dev</a></li><li><strong>Contact:</strong> Volti Sodala (via <a href="/en/mitmachen.html">Tip-Line</a> or <a href="https://ko-fi.com/voltisodala" target="_blank" rel="noreferrer">Ko-fi</a>)</li></ul><hr><p><em>&quot;We can tell the truth as long as we claim it&#39;s invented.&quot;</em></p>',19)])])}const p=t(i,[["render",s]]);export{m as __pageData,p as default};
